def solve(text: str) -> str:
    toks = text.split()
    a, b = int(toks[0]), int(toks[1])
    phi = (1 + 5 ** 0.5) / 2
    cold = set()
    n = 0
    while n <= 100:
        lo = int(n * phi)
        hi = int(n * phi * phi)
        if lo > 25 and hi > 25:
            break
        if lo <= 25 and hi <= 25:
            cold.add((lo, hi))
            cold.add((hi, lo))
        n += 1
    if (a, b) in cold:
        return "LOSE"
    best = None
    for i in range(0, a + 1):
        for j in range(0, b + 1):
            if i == 0 and j == 0:
                continue
            if i > 0 and j > 0 and i != j:
                continue
            na, nb = a - i, b - j
            if (na, nb) in cold:
                if best is None or (i, j) < best:
                    best = (i, j)
    return "WIN %d %d" % best
